import * as crypto from 'crypto'
import * as fs from 'fs'
import * as path from 'path'
import { pipeline } from 'stream/promises'
import { RequestError, UnauthorizedError } from './api-utils'

const PUBLIC_TOKEN_SIZE = 64

export function registerStorageService(fileModel, targetDir: any): any {
    return {
        saveDataToFile: async (id, fileData) => {
            if (id) {
                const existFile = await fileModel.findById(id).select({ __path: 1 }).lean()
                fileData.__path = existFile.__path
            }

            if (!fileData.__path) {
                fileData.publicKey = await generateUniqFilePublicKey(fileModel)
                fileData.__path = path.join(targetDir, fileData.publicKey)
            }

            await new Promise((resolve, reject) =>
                fs.writeFile(fileData.__path, fileData.data, (err) => {
                    if (err) return reject(err)
                    fs.stat(fileData.__path, (err2, stat) => {
                        if (err2) return reject(err2)
                        fileData.size = stat.size
                        resolve(true)
                    })
                }),
            )
        },
        loadDataFromFile: async (fileData, data, context) => {
            const fullPath = path.resolve(fileData.__path)

            return await new Promise((resolve, reject) =>
                fs.stat(fullPath, (err, exists) => {
                    if (!exists) return reject(`System error file with key: '${fileData.publicKey}' doesn't exist`)

                    fs.readFile(fullPath, (err, data) => (err ? reject(err) : resolve(data.toString())))
                }),
            )
        },
        unlinkFile: async (id) => {
            const existFile = await fileModel.findById(id).select({ __path: 1 }).lean()
            const filePath = existFile.__path

            return await new Promise((resolve, reject) => fs.unlink(filePath, (err) => (err ? reject(err) : resolve(true))))
        },
    }
}

export function registerStorageRouter(entry: any, router: any, targetDir: any) {
    const fileService = entry.services['file']
    const fileModel = entry.models['file']
    const userModel = entry.models['user']

    router.post('/upload', async (request) => {
        const user = request.user
        if (!user?.id || !await userModel.exists({ _id: user.id })) throw new UnauthorizedError()
        if (!request.isMultipart()) throw new RequestError('Upload expects multipart form with file')

        let result
        // Fastify removes temporary files after the response, including on errors.
        const { files: uploadingFiles } = await request.saveRequestFiles()
        if (!uploadingFiles.length) throw new RequestError('Upload expects multipart form with file')
        for (const upload of uploadingFiles) {
            const { filepath, filename: name, mimetype: type } = upload
            const publicKey = await generateUniqFilePublicKey(fileModel)
            const __path = path.join(targetDir, publicKey)
            const size = (await fs.promises.stat(filepath)).size
            try {
                // Copy works even when the OS temp directory is on another filesystem.
                await pipeline(fs.createReadStream(filepath), fs.createWriteStream(__path, { flags: 'wx' }))
                const file = await fileService.create({ name, type, size, __path, publicKey, userId: user.id })
                result = { id: file._id, publicKey, name, type, size }
            } catch (error) {
                await fs.promises.rm(__path, { force: true })
                throw error
            }
        }
        return result
    })

    router.get('/download/:id', async (request, reply) => {
        const { id } = request.params
        // Public keys are 128 hex characters. Both MongoDB and SQL model IDs
        // require authentication; do not mistake a SQL UUID for a public key.
        const isPublicKey = /^[0-9a-f]{128}$/.test(id)
        if (!isPublicKey && !request.user?.id) throw new UnauthorizedError()
        const file = isPublicKey
            ? await fileModel.findOne({ publicKey: id }).lean()
            : await fileModel.findById(id).lean()
        if (!file) throw new RequestError('File not found', 404)
        const fullPath = path.resolve(file.__path)
        const stat = await fs.promises.stat(fullPath)
        reply.header('Content-disposition', `attachment; filename*=UTF-8''${encodeURIComponent(file.name)}`)
        reply.header('Content-length', stat.size)
        reply.type(file.type || 'application/octet-stream')
        return reply.send(fs.createReadStream(fullPath))
    })
}

export async function generateUniqFilePublicKey(fileModel) {
    let publicKey: string

    do {
        publicKey = crypto.randomBytes(PUBLIC_TOKEN_SIZE).toString('hex')
    } while (await fileModel.exists({ publicKey }))

    return publicKey
}

export function generateUniqFileName(targetDir: string) {
    let base: string, fullPath: string

    do {
        base = crypto.randomBytes(PUBLIC_TOKEN_SIZE).toString('hex')
        fullPath = path.join(targetDir, base)
    } while (fs.existsSync(fullPath))

    return [fullPath, base]
}
